// This is a simplified representation of what a Vue.js bundle would look like
// In a real implementation, this would be generated by Vue CLI/Webpack

// Define the Vue components
(function() {
    // Message Component
    Vue.component('chat-message', {
        props: ['message'],
        template: `
            <div class="message" :class="[message.role, message.is_loading ? 'loading' : '']">
                <div class="message-content">
                    <div class="message-bubble">
                        <div v-if="message.is_loading" class="loading-indicator">
                            <span class="dot"></span>
                            <span class="dot"></span>
                            <span class="dot"></span>
                        </div>
                        <div v-else>{{ message.content }}</div>
                    </div>
                </div>
                <div class="message-meta">
                    <span class="message-role">{{ message.role }}</span>
                    <span class="message-time">{{ formatTimestamp(message.timestamp) }}</span>
                </div>
            </div>
        `,
        methods: {
            formatTimestamp: function(timestamp) {
                if (!timestamp) return '';
                const date = new Date(timestamp);
                return date.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'});
            }
        }
    });

    // Message Input Component
    Vue.component('message-input', {
        props: ['session_id'],
        data: function() {
            return {
                content: '',
                is_sending: false
            };
        },
        template: `
            <div class="message-input-container">
                <textarea 
                    v-model="content"
                    placeholder="Type a message..."
                    @keyup.enter="sendMessage"
                    :disabled="is_sending"
                    rows="1"
                    class="message-input"
                ></textarea>
                <button 
                    @click="sendMessage"
                    :disabled="is_sending || !content.trim()"
                    class="send-button"
                >
                    Send
                </button>
            </div>
        `,
        methods: {
            sendMessage: function() {
                if (!this.content.trim() || this.is_sending) return;
                
                const content = this.content;
                this.content = '';
                this.is_sending = true;
                
                // Emit event to parent
                this.$emit('send-message', content);
                
                // Reset sending state after a short delay (in real app, this would be based on API response)
                setTimeout(() => {
                    this.is_sending = false;
                }, 1000);
            }
        }
    });

    // Session Sidebar Component
    Vue.component('session-sidebar', {
        props: ['sessions', 'active_session'],
        template: `
            <div class="session-sidebar">
                <h3>Sessions</h3>
                <button @click="$emit('new-session')" class="new-session-btn">New Chat</button>
                <ul class="session-list">
                    <li 
                        v-for="session in sessions"
                        :key="session.name"
                        :class="{ active: session.name === active_session }"
                        @click="$emit('select-session', session.name)"
                    >
                        <div class="session-info">
                            <div class="session-title">{{ session.user_id || 'Unknown User' }}</div>
                            <div class="session-time">{{ formatDate(session.start_time) }}</div>
                        </div>
                        <span class="session-status" :class="session.status">{{ session.status }}</span>
                    </li>
                </ul>
            </div>
        `,
        methods: {
            formatDate: function(datetime) {
                if (!datetime) return '';
                const date = new Date(datetime);
                return date.toLocaleDateString([], {month: 'short', day: 'numeric'});
            }
        }
    });

    // Main App Component
    Vue.component('ai-chat-app', {
        data: function() {
            return {
                sessions: [],
                active_session: null,
                messages: [],
                is_loading: false,
                is_sending: false,
                new_message_content: ''
            };
        },
        created: function() {
            this.loadSessions();
        },
        template: `
            <div class="ai-chat-container">
                <session-sidebar 
                    :sessions="sessions"
                    :active_session="active_session"
                    @new-session="createNewSession"
                    @select-session="selectSession"
                ></session-sidebar>
                
                <div class="chat-main">
                    <div class="chat-header">
                        <h2>AI Chat</h2>
                        <div class="session-status" v-if="active_session">
                            Active session: {{ active_session }}
                        </div>
                    </div>
                    
                    <div class="chat-messages">
                        <chat-message 
                            v-for="message in messages"
                            :key="message.name"
                            :message="message"
                        ></chat-message>
                        
                        <!-- Loading indicator -->
                        <div v-if="is_loading" class="loading-indicator">
                            <span class="dot"></span>
                            <span class="dot"></span>
                            <span class="dot"></span>
                        </div>
                    </div>
                    
                    <message-input 
                        :session_id="active_session"
                        @send-message="handleSendMessage"
                    ></message-input>
                </div>
            </div>
        `,
        methods: {
            loadSessions: function() {
                this.is_loading = true;
                frappe.call({
                    method: "frappe_ai_chat.api.get_sessions",
                    callback: function(r) {
                        if (r.message) {
                            this.sessions = r.message;
                            // Auto-select the most recent session or create a new one
                            if (this.sessions.length > 0) {
                                this.selectSession(this.sessions[0].name);
                            } else {
                                this.createNewSession();
                            }
                        }
                        this.is_loading = false;
                    }.bind(this),
                    error: function(r) {
                        frappe.msgprint(__("Failed to load sessions"));
                        this.is_loading = false;
                    }
                });
            },
            createNewSession: function() {
                this.is_loading = true;
                frappe.call({
                    method: "frappe_ai_chat.api.create_session",
                    callback: function(r) {
                        if (r.message) {
                            const newSession = r.message;
                            this.sessions.unshift(newSession);
                            this.selectSession(newSession.name);
                        }
                        this.is_loading = false;
                    }.bind(this),
                    error: function(r) {
                        frappe.msgprint(__("Failed to create session"));
                        this.is_loading = false;
                    }
                });
            },
            selectSession: function(session_id) {
                this.active_session = session_id;
                this.loadMessages();
            },
            loadMessages: function() {
                if (!this.active_session) return;
                
                this.is_loading = true;
                frappe.call({
                    method: "frappe_ai_chat.api.get_messages",
                    args: { session: this.active_session },
                    callback: function(r) {
                        if (r.message) {
                            this.messages = r.message.map(msg => ({
                                ...msg,
                                role: msg.role.charAt(0).toUpperCase() + msg.role.slice(1).toLowerCase() // Capitalize first letter
                            }));
                        }
                        this.is_loading = false;
                    }.bind(this),
                    error: function(r) {
                        frappe.msgprint(__("Failed to load messages"));
                        this.is_loading = false;
                    }
                });
            },
            handleSendMessage: function(content) {
                if (!this.active_session) {
                    frappe.msgprint(__("Please select or create a session first"));
                    return;
                }
                
                this.is_sending = true;
                frappe.call({
                    method: "frappe_ai_chat.api.send_message",
                    args: {
                        session: this.active_session,
                        content: content
                    },
                    callback: function(r) {
                        if (r.message) {
                            // Add both user and AI messages to the list
                            const userMsg = r.message.user_message;
                            const aiMsg = r.message.ai_message;
                            
                            // Format messages for display
                            const formattedUserMsg = {
                                ...userMsg,
                                role: userMsg.role.charAt(0).toUpperCase() + userMsg.role.slice(1).toLowerCase()
                            };
                            const formattedAiMsg = {
                                ...aiMsg,
                                role: aiMsg.role.charAt(0).toUpperCase() + aiMsg.role.slice(1).toLowerCase()
                            };
                            
                            this.messages.push(formattedUserMsg);
                            this.messages.push(formattedAiMsg);
                            
                            // Scroll to bottom
                            this.$nextTick(() => {
                                const messagesContainer = this.$el.querySelector('.chat-messages');
                                messagesContainer.scrollTop = messagesContainer.scrollHeight;
                            });
                        }
                        this.is_sending = false;
                    }.bind(this),
                    error: function(r) {
                        frappe.msgprint(__("Failed to send message"));
                        this.is_sending = false;
                    }
                });
            }
        }
    });

    // Initialize the app when Frappe is ready
    frappe.ready(function() {
        // Check if we're on the AI Chat page
        if (window.location.pathname.includes('/ai-chat') || 
            frappe.route_options && frappe.route_options.page === 'ai-chat') {
            
            new Vue({
                el: '#ai-chat-app',
                render: h => h('ai-chat-app')
            });
        }
    });
    
    // Expose for testing
    window.frappe_ai_chat = {
        App: Vue.extend({
            render: h => h('ai-chat-app')
        })
    };
})();